package com.example.starter.domain;

/**
 * 封锁申请生命周期状态。
 *
 * <p>合法迁移：
 * <ul>
 *     <li>PENDING → APPROVED（审批）/ CANCELLED（取消）/ PREEMPTED（被紧急申请抢占）</li>
 *     <li>APPROVED → ACTIVE（激活）/ CANCELLED（取消）/ PREEMPTED（被紧急申请抢占）</li>
 *     <li>ACTIVE → COMPLETED（完成）；激活后不可取消、不可抢占</li>
 * </ul>
 * COMPLETED、CANCELLED、PREEMPTED 为终态。
 */
public enum RequestStatus {
    PENDING,
    APPROVED,
    ACTIVE,
    COMPLETED,
    CANCELLED,
    PREEMPTED;

    public boolean isTerminal() {
        return this == COMPLETED || this == CANCELLED || this == PREEMPTED;
    }
}

package com.example.starter.domain;

/**
 * 携带请求键与版本的状态操作类型。
 */
public enum OperationType {
    APPROVE,
    ACTIVATE,
    COMPLETE,
    CANCEL
}

package com.example.starter.domain;

import java.time.Instant;
import java.util.List;

/**
 * 封锁申请领域模型（含区段与版本）。所有时间为 UTC；占用窗为半开区间
 * {@code [bufferedStart, bufferedEnd)}，端点相接不冲突。
 */
public record PossessionRequest(
        String id,
        List<String> sectionIds,
        Instant start,
        Instant end,
        Instant bufferedStart,
        Instant bufferedEnd,
        long preBufferSeconds,
        long postBufferSeconds,
        int priority,
        RequestStatus status,
        int version,
        Instant businessTime,
        Instant createdAt
) {
}

package com.example.starter.exception;

import java.util.List;

/**
 * 审批/抢占因时间窗冲突被拒绝。HTTP 409，响应体携带按区段与时间排序的冲突明细。
 */
public class ConflictException extends RuntimeException {

    private final List<ConflictDetail> conflicts;

    public ConflictException(String message, List<ConflictDetail> conflicts) {
        super(message);
        this.conflicts = List.copyOf(conflicts);
    }

    public List<ConflictDetail> getConflicts() {
        return conflicts;
    }

    /**
     * 单条冲突明细：申请在某个区段上与既有占用窗正长度重叠。
     */
    public record ConflictDetail(
            String sectionId,
            String conflictingRequestId,
            String conflictingStatus,
            java.time.Instant conflictingBufferedStart,
            java.time.Instant conflictingBufferedEnd,
            java.time.Instant overlapStart,
            java.time.Instant overlapEnd
    ) {
    }
}

package com.example.starter.exception;

/**
 * 404：申请或快照不存在。
 */
public class NotFoundException extends RuntimeException {
    public NotFoundException(String message) {
        super(message);
    }
}

package com.example.starter.exception;

/**
 * 422：业务规则违例（非法状态迁移、expectedVersion 不匹配、同操作异参复用请求键等）。
 */
public class BusinessRuleException extends RuntimeException {
    public BusinessRuleException(String message) {
        super(message);
    }
}

