    public record ConflictDetail(
            String sectionId,
            String conflictingRequestId,
            String conflictingStatus,
            java.time.Instant conflictingBufferedStart,
            java.time.Instant conflictingBufferedEnd,
            java.time.Instant overlapStart,
            java.time.Instant overlapEnd
    ) {
    }
}

